"""Specification tests for the generated application (generated by the FORGE AI QA Agent).

These tests are derived from the dynamic specification - role permissions, workflows, business
rules, dashboard metrics, reports and explicitly listed records - so every generated app is
tested against what its own prompt asked for, not against a fixed template.
"""

import json
from typing import List, Optional

from backend.codegen.blueprint import BEntity, BField, Blueprint
from backend.codegen.spec_runtime import entity_rule_config


def _q(value) -> str:
    """Python literal for a JSON-like value."""
    return json.dumps(value).replace("true", "True").replace("false", "False").replace("null", "None")


def _creator(bp: Blueprint, e: BEntity) -> str:
    return "user_headers" if bp.can(bp.default_role, e.name, "create") else "admin_headers"


def _args(*names: str) -> str:
    return ", ".join(sorted(set(names)))


def _shift(f: BField, earlier: bool):
    """Two ordered sample values for a date/datetime/time field."""
    if f.kind == "date":
        return "2025-06-10" if earlier else "2025-06-15"
    if f.kind == "datetime":
        return "2025-06-10T09:00:00" if earlier else "2025-06-15T09:00:00"
    if f.kind == "time":
        return "09:00" if earlier else "10:30"
    return None


# ---------------------------------------------------------------------------------------------
# permissions
# ---------------------------------------------------------------------------------------------

def render_permission_tests(bp: Blueprint) -> str:
    lines = [
        '"""Role permissions from the specification (generated by FORGE AI QA Agent)."""',
        "",
        "import factories",
        "",
        f"PERMISSIONS = {_q(bp.permissions)}",
        f"ADMIN_ROLES = {_q(bp.admin_roles)}",
        f"ENDPOINTS = {_q({e.name: e.api_path for e in bp.entities})}",
        f"FACTORIES = {_q({e.name: 'make_' + e.snake for e in bp.entities})}",
        f"ADMIN_ONLY_PARENTS = {_q({e.name: _creator(bp, e) == 'admin_headers' for e in bp.entities})}",
        "",
        "",
        "def test_every_role_has_a_permission_row():",
        f"    assert set(PERMISSIONS) == set({_q(bp.roles)})",
        "",
    ]
    for role in bp.roles:
        if role in bp.admin_roles:
            continue
        ident = role.replace("-", "_")
        lines += [
            "",
            f"def test_{ident}_permissions(client, role_headers, admin_headers):",
            f'    headers = role_headers("{role}")',
            f'    for entity, actions in PERMISSIONS["{role}"].items():',
            "        endpoint = ENDPOINTS[entity]",
            "        assert client.get(endpoint, headers=headers).status_code == (200 if 'read' in actions else 403), entity",
            "        if 'create' in actions:",
            "            make = getattr(factories, FACTORIES[entity])",
            "            created = make(client, headers, admin_headers)",
            "        else:",
            "            assert client.post(endpoint, json={}, headers=headers).status_code == 403, entity",
            "            created = getattr(factories, FACTORIES[entity])(client, admin_headers, admin_headers)",
            "        if 'update' not in actions:",
            "            assert client.put(f\"{endpoint}/{created['id']}\", json={}, headers=headers).status_code in (403, 404), entity",
            "        if 'delete' not in actions:",
            "            assert client.delete(f\"{endpoint}/{created['id']}\", headers=headers).status_code in (403, 404), entity",
            "",
        ]
    return "\n".join(lines) + "\n"


# ---------------------------------------------------------------------------------------------
# workflows
# ---------------------------------------------------------------------------------------------

def render_workflow_tests(bp: Blueprint) -> Optional[str]:
    blocks: List[str] = []
    for e in bp.entities:
        cfg = entity_rule_config(bp, e)
        transitions = cfg["transitions"]
        status = e.get_field(cfg["workflow_field"])
        if not transitions or not status or not status.enum_values:
            continue
        creator = _creator(bp, e)
        mk = f"make_{e.snake}"
        initial = status.default or status.enum_values[0]
        first = next(((a, t) for a, t in transitions.items() if not t["from"] or initial in t["from"]), None)
        if not first:
            continue
        action, t = first
        blocks += [
            "",
            f"def test_{e.snake}_{action}_moves_to_{t['to']}(client, {_args(creator, 'admin_headers')}):",
            f"    created = factories.{mk}(client, {creator}, admin_headers, {status.name}={_q(initial)})",
            f"    response = client.post(f\"{e.api_path}/{{created['id']}}/actions/{action}\", headers={creator})",
            "    assert response.status_code == 200, response.text",
            f"    assert response.json()[{_q(status.name)}] == {_q(t['to'])}",
        ]
        blocked = next(((a2, t2) for a2, t2 in transitions.items() if t2["from"] and t["to"] not in t2["from"]), None)
        if blocked:
            a2 = blocked[0]
            blocks += [
                f"    again = client.post(f\"{e.api_path}/{{created['id']}}/actions/{a2}\", headers={creator})",
                "    assert again.status_code == 409, again.text",
            ]
        blocks += [
            "",
            "",
            f"def test_{e.snake}_unknown_action_is_rejected(client, {_args(creator, 'admin_headers')}):",
            f"    created = factories.{mk}(client, {creator}, admin_headers)",
            f"    response = client.post(f\"{e.api_path}/{{created['id']}}/actions/not-a-step\", headers={creator})",
            "    assert response.status_code == 404",
            "",
        ]
        denied = next((r for r in bp.roles if not bp.can(r, e.name, "update")), None)
        if denied:
            blocks += [
                "",
                f"def test_{e.snake}_workflow_requires_update_permission(client, role_headers, admin_headers):",
                f"    created = factories.{mk}(client, admin_headers, admin_headers, {status.name}={_q(initial)})",
                f"    response = client.post(f\"{e.api_path}/{{created['id']}}/actions/{action}\", headers=role_headers({_q(denied)}))",
                "    assert response.status_code == 403",
                "",
            ]
    if not blocks:
        return None
    return '"""Workflow steps from the specification (generated by FORGE AI QA Agent)."""\n\nimport factories\n' + "\n".join(blocks) + "\n"


# ---------------------------------------------------------------------------------------------
# business rules
# ---------------------------------------------------------------------------------------------

def render_rule_tests(bp: Blueprint) -> Optional[str]:
    blocks: List[str] = []
    for e in bp.entities:
        cfg = entity_rule_config(bp, e)
        creator = _creator(bp, e)
        mk = f"make_{e.snake}"
        for start, end, _message in cfg["date_order"]:
            fs, fe = e.get_field(start), e.get_field(end)
            if fs.kind != fe.kind or _shift(fs, True) is None:
                continue
            blocks += [
                "",
                f"def test_{e.snake}_{end}_cannot_precede_{start}(client, {_args(creator, 'admin_headers')}):",
                "    try:",
                f"        factories.{mk}(client, {creator}, admin_headers, {start}={_q(_shift(fs, False))}, {end}={_q(_shift(fe, True))})",
                "    except AssertionError as exc:",
                "        assert '422' in str(exc) or 'cannot be before' in str(exc)",
                "    else:",
                "        raise AssertionError('an end before the start was accepted')",
                f"    ok = factories.{mk}(client, {creator}, admin_headers, {start}={_q(_shift(fs, True))}, {end}={_q(_shift(fe, False))})",
                f"    assert ok[{_q(end)}] is not None",
                "",
            ]
        for target, left, right, op in cfg["computed"]:
            first, after = (4000, 1000) if op == "multiply" else (60, 0)
            blocks += [
                "",
                f"def test_{e.snake}_{target}_is_computed(client, {_args(creator, 'admin_headers')}):",
                f"    created = factories.{mk}(client, {creator}, admin_headers, {left}=100, {right}=40)",
                f"    assert abs(created[{_q(target)}] - {first}) < 0.001",
                f"    updated = client.put(f\"{e.api_path}/{{created['id']}}\", json={{{_q(right)}: {10 if op == 'multiply' else 100}}}, headers={creator}).json()",
                f"    assert abs(updated[{_q(target)}] - {after}) < 0.001",
                "",
            ]
        for fields, _status_field, _ignored, _message in cfg["unique"]:
            setup, values = [], {}
            for name in fields:
                f = e.get_field(name)
                if f.kind == "reference":
                    parent = bp.entity(f.references)
                    setup.append(f"    {name} = factories.make_{parent.snake}(client, {_creator(bp, parent)}, admin_headers)['id']")
                    values[name] = name
                else:
                    values[name] = _q(_shift(f, False) if f.kind in ("date", "datetime", "time") else "QA same value")
            args = ", ".join(f"{k}={v}" for k, v in values.items())
            fixtures = sorted({creator, "admin_headers", *[_creator(bp, bp.entity(e.get_field(n).references))
                                                            for n in fields if e.get_field(n).kind == "reference"]})
            blocks += [
                "",
                f"def test_{e.snake}_duplicate_{'_'.join(fields)}_is_rejected(client, {', '.join(fixtures)}):",
                *setup,
                f"    factories.{mk}(client, {creator}, admin_headers, {args})",
                "    try:",
                f"        factories.{mk}(client, {creator}, admin_headers, {args})",
                "    except AssertionError as exc:",
                "        assert '409' in str(exc) or 'already exists' in str(exc)",
                "    else:",
                "        raise AssertionError('a duplicate was accepted')",
                "",
            ]
        for alloc in cfg["allocations"]:
            resource = bp.entity(alloc["resource"])
            res_creator = _creator(bp, resource)
            release = next(((a, t) for a, t in cfg["transitions"].items() if t["to"] in alloc["release"]), None)
            fixtures = sorted({creator, res_creator, "admin_headers"})
            blocks += [
                "",
                f"def test_{e.snake}_allocates_{resource.snake}(client, {', '.join(fixtures)}):",
                f"    resource = factories.make_{resource.snake}(client, {res_creator}, admin_headers, status={_q(alloc['available'])})",
                f"    holder = factories.{mk}(client, {creator}, admin_headers, {alloc['field']}=resource['id'])",
                f"    current = client.get(f\"{resource.api_path}/{{resource['id']}}\", headers=admin_headers).json()",
                f"    assert current['status'] == {_q(alloc['occupied'])}",
                "    try:",
                f"        factories.{mk}(client, {creator}, admin_headers, {alloc['field']}=resource['id'])",
                "    except AssertionError as exc:",
                "        assert '409' in str(exc) or 'not available' in str(exc)",
                "    else:",
                "        raise AssertionError('an occupied resource was allocated twice')",
            ]
            if release:
                blocks.append(f"    released = client.post(f\"{e.api_path}/{{holder['id']}}/actions/{release[0]}\", headers=admin_headers)")
            else:
                blocks.append(f"    released = client.delete(f\"{e.api_path}/{{holder['id']}}\", headers=admin_headers)")
            blocks += [
                "    assert released.status_code == 200, released.text",
                f"    current = client.get(f\"{resource.api_path}/{{resource['id']}}\", headers=admin_headers).json()",
                f"    assert current['status'] == {_q(alloc['available'])}",
                "",
            ]
    if not blocks:
        return None
    return '"""Business rules from the specification (generated by FORGE AI QA Agent)."""\n\nimport factories\n' + "\n".join(blocks) + "\n"


# ---------------------------------------------------------------------------------------------
# dashboard metrics, reports and explicit records
# ---------------------------------------------------------------------------------------------

def render_metric_tests(bp: Blueprint) -> str:
    count_metric = next((m for m in bp.metrics if m["kind"] == "count" and m.get("entity")), None)
    lines = [
        '"""Dashboard metrics from the specification (generated by FORGE AI QA Agent)."""',
        "",
        "import factories",
        "",
        f"METRIC_IDS = {_q([m['id'] for m in bp.metrics])}",
        "",
        "",
        "def test_dashboard_exposes_every_specified_metric(client, user_headers):",
        '    response = client.get("/api/dashboard/metrics", headers=user_headers)',
        "    assert response.status_code == 200, response.text",
        "    assert [m['id'] for m in response.json()['metrics']] == METRIC_IDS",
        "",
        "",
        "def test_dashboard_metrics_require_authentication(client):",
        '    assert client.get("/api/dashboard/metrics").status_code == 401',
        "",
    ]
    if count_metric:
        e = bp.entity(count_metric["entity"])
        creator = _creator(bp, e)
        lines += [
            "",
            f"def test_count_metric_reflects_live_records(client, {', '.join(sorted({creator, 'admin_headers'}))}):",
            f"    factories.make_{e.snake}(client, {creator}, admin_headers)",
            f'    total = client.get("{e.api_path}", params={{"limit": 1}}, headers=admin_headers).json()["total"]',
            '    metrics = client.get("/api/dashboard/metrics", headers=admin_headers).json()["metrics"]',
            f"    metric = next(m for m in metrics if m['id'] == {_q(count_metric['id'])})",
            "    assert metric['value'] == total",
            "",
        ]
    return "\n".join(lines) + "\n"


def render_report_tests(bp: Blueprint) -> str:
    return '''"""Reports module (generated by FORGE AI QA Agent)."""


def test_reports_cover_every_module(client, user_headers):
    response = client.get("/api/reports", headers=user_headers)
    assert response.status_code == 200, response.text
    assert {section["entity"] for section in response.json()["sections"]} == set(%s)


def test_reports_validate_date_range(client, user_headers):
    response = client.get("/api/reports", params={"date_from": "2025-02-01", "date_to": "2025-01-01"}, headers=user_headers)
    assert response.status_code == 422
''' % _q([e.name for e in bp.entities])


def render_seed_tests(bp: Blueprint) -> Optional[str]:
    if not bp.seed_records:
        return None
    lines = ['"""Records listed in the prompt are seeded (generated by FORGE AI QA Agent)."""', "", "",
             "def test_listed_records_are_seeded(client, admin_headers, monkeypatch):",
             '    monkeypatch.setenv("SEED_DATA", "1")',
             "    from app.seed_data import seed_reference_data",
             "    seed_reference_data()",
             "    seed_reference_data()  # idempotent"]
    for name, rows in bp.seed_records.items():
        e = bp.entity(name)
        for row in rows[:3]:
            value = row.get(e.display_field)
            if value is None:
                continue
            lines += [f'    found = client.get("{e.api_path}", params={{"q": {_q(value)}, "limit": 50}}, headers=admin_headers).json()',
                      f"    assert sum(1 for item in found['items'] if item[{_q(e.display_field)}] == {_q(value)}) == 1"]
    return "\n".join(lines) + "\n"


def write_spec_tests(bp: Blueprint, project, agent: str) -> List[str]:
    project.write("backend/tests/test_permissions.py", render_permission_tests(bp), agent)
    project.write("backend/tests/test_dashboard_metrics.py", render_metric_tests(bp), agent)
    for path, content in (("backend/tests/test_workflows.py", render_workflow_tests(bp)),
                          ("backend/tests/test_business_rules.py", render_rule_tests(bp)),
                          ("backend/tests/test_seed_records.py", render_seed_tests(bp)),
                          ("backend/tests/test_reports.py", render_report_tests(bp) if bp.has_reports else None)):
        if content:
            project.write(path, content, agent)
    return project.files_by_agent(agent)
